def int_to_roman(num):
    val = [
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4,
        1
    ]
    syms = [
        "M", "CM", "D", "CD",
        "C", "XC", "L", "XL",
        "X", "IX", "V", "IV",
        "I"
    ]
    roman_num = ''
    i = 0
    while num > 0:
        for _ in range(num // val[i]):
            roman_num += syms[i]
            num -= val[i]
        i += 1
    return roman_num

def convert_to_roman(input_num):
    if not isinstance(input_num, int) or input_num <= 0:
        return "Invalid input"

    special_cases = {
        4: "IV",
        9: "IX",
        40: "XL",
        90: "XC",
        400: "CD",
        900: "CM"
    }

    if input_num in special_cases:
        return special_cases[input_num]

    return int_to_roman(input_num)

# Test the program with various input values
test_values = [3, 4, 9, 58, 1994]
for value in test_values:
    print(f"{value} -> {convert_to_roman(value)}")

